import static com.fream.back.domain.event.entity.QEvent.event;
import static com.fream.back.domain.product.entity.QBrand.brand;

@Repository
@RequiredArgsConstructor
@Slf4j
public class EventRepositoryImpl implements EventRepositoryCustom {

    private final JPAQueryFactory queryFactory;

    /**
     * 검색 조건에 따른 이벤트 페이징 조회
     */
    @Override
    public Page<Event> searchEvents(EventSearchCondition condition, Pageable pageable) {
        log.debug("이벤트 검색 수행: condition={}", condition);

        // 조건에 맞는 결과 조회
        JPAQuery<Event> query = queryFactory
                .selectFrom(event)
                .join(event.brand, brand).fetchJoin()
                .where(
                        keywordContains(condition.getKeyword()),
                        brandIdEquals(condition.getBrandId()),
                        isActiveEquals(condition.getIsActive()),
                        startDateAfter(condition.getStartDate()),
                        endDateBefore(condition.getEndDate()),
                        statusEquals(condition.getStatus())
                );

        // 카운트 쿼리 최적화를 위한 별도 쿼리
        JPAQuery<Long> countQuery = queryFactory
                .select(event.count())
                .from(event)
                .join(event.brand, brand)
                .where(
                        keywordContains(condition.getKeyword()),
                        brandIdEquals(condition.getBrandId()),
                        isActiveEquals(condition.getIsActive()),
                        startDateAfter(condition.getStartDate()),
                        endDateBefore(condition.getEndDate()),
                        statusEquals(condition.getStatus())
                );

        // 정렬 및 페이징 처리
        OrderSpecifier<?>[] orderSpecifiers = getOrderSpecifier(pageable.getSort(), event);
        List<Event> content = query
                .offset(pageable.getOffset())
                .limit(pageable.getPageSize())
                .orderBy(orderSpecifiers)
                .fetch();

        // 결과가 없으면 빈 페이지 반환 (최적화)
        if (content.isEmpty()) {
            return Page.empty(pageable);
        }

        // 조회 결과 로깅
        log.debug("이벤트 검색 결과: 개수={}", content.size());

        return PageableExecutionUtils.getPage(content, pageable, countQuery::fetchOne);
    }

    /**
     * 제목 키워드 검색 조건
public class NoticeRepositoryImpl implements NoticeRepositoryCustom {

    private final JPAQueryFactory queryFactory;

    @Override
    public Page<Notice> searchNotices(String keyword, Pageable pageable) {
        BooleanBuilder builder = new BooleanBuilder();

        // 키워드 검색 조건 추가
        if (StringUtils.hasText(keyword)) {
            builder.and(containsKeyword(keyword));
        }

        // 결과 조회
        List<Notice> results = queryFactory.selectFrom(notice)
                .where(builder)
                .orderBy(notice.createdDate.desc()) // 최신순 정렬
                .offset(pageable.getOffset())
                .limit(pageable.getPageSize())
                .fetch();

        // 전체 결과 수 조회
        Long total = queryFactory.select(notice.count())
                .from(notice)
                .where(builder)
                .fetchOne();

        return new PageImpl<>(results, pageable, Objects.requireNonNullElse(total, 0L));
    }

    @Override
    public Page<Notice> searchNoticesByCategoryAndKeyword(NoticeCategory category, String keyword, Pageable pageable) {
        BooleanBuilder builder = new BooleanBuilder();

        // 카테고리 검색 조건 추가
        if (category != null) {
            builder.and(notice.category.eq(category));
        }

        // 키워드 검색 조건 추가
        if (StringUtils.hasText(keyword)) {
            builder.and(containsKeyword(keyword));
        }

        // 결과 조회
        List<Notice> results = queryFactory.selectFrom(notice)
                .where(builder)
                .orderBy(notice.createdDate.desc()) // 최신순 정렬
                .offset(pageable.getOffset())
                .limit(pageable.getPageSize())
                .fetch();

        // 전체 결과 수 조회
        Long total = queryFactory.select(notice.count())
                .from(notice)
                .where(builder)
                .fetchOne();

        return new PageImpl<>(results, pageable, Objects.requireNonNullElse(total, 0L));
    }

    @Override
    public Page<FAQ> searchFAQs(String keyword, Pageable pageable) {
        BooleanBuilder builder = new BooleanBuilder();

        if (keyword != null && !keyword.isEmpty()) {
            // 대소문자 무시와 한글 검색을 위한 like 사용
            builder.or(fAQ.question.like("%" + keyword + "%"))
                    .or(fAQ.answer.like("%" + keyword + "%"));
        }

        List<FAQ> results = queryFactory.selectFrom(fAQ)
                .where(builder)
                .offset(pageable.getOffset())
                .limit(pageable.getPageSize())
                .fetch();

        long total = queryFactory.select(fAQ.count())
                .from(fAQ)
                .where(builder)
                .fetchOne();

        return new PageImpl<>(results, pageable, total);
    }
}
    private final JPAQueryFactory queryFactory;

    private final QNotification notification = QNotification.notification;
    private final QUser user = QUser.user;

    @Override
    public List<Notification> findByUserEmailAndCategory(String email, NotificationCategory category) {
        return queryFactory
                .selectFrom(notification)
                .join(notification.user, user).fetchJoin()
                .where(
                        userEmailEq(email),
                        categoryEq(category)
                )
                .orderBy(notification.createdDate.desc())
                .fetch();
    }

    @Override
    public List<Notification> findByUserEmailAndType(String email, NotificationType type) {
        return queryFactory
                .selectFrom(notification)
                .join(notification.user, user).fetchJoin()
                .where(
                        userEmailEq(email),
                        typeEq(type)
                )
                .orderBy(notification.createdDate.desc())
                .fetch();
    }

    @Override
    public Page<Notification> findByUserEmailAndIsRead(String email, boolean isRead, Pageable pageable) {
        List<Notification> content = queryFactory
                .selectFrom(notification)
                .join(notification.user, user).fetchJoin()
                .where(
                        userEmailEq(email),
                        isReadEq(isRead)
                )
                .orderBy(getOrderSpecifiers(pageable).toArray(OrderSpecifier[]::new))
                .offset(pageable.getOffset())
                .limit(pageable.getPageSize())
                .fetch();

        JPAQuery<Long> countQuery = queryFactory
                .select(notification.count())
                .from(notification)
                .join(notification.user, user)
                .where(
                        userEmailEq(email),
                        isReadEq(isRead)
                );

        return PageableExecutionUtils.getPage(content, pageable, countQuery::fetchOne);
    }

    @Override
    public Page<Notification> findByUserEmailAndCategoryAndIsRead(
            String email, NotificationCategory category, boolean isRead, Pageable pageable) {
        List<Notification> content = queryFactory
                .selectFrom(notification)
                .join(notification.user, user).fetchJoin()
                .where(
                        userEmailEq(email),
                        categoryEq(category),
                        isReadEq(isRead)
                )
                .orderBy(getOrderSpecifiers(pageable).toArray(OrderSpecifier[]::new))
                .offset(pageable.getOffset())
                .limit(pageable.getPageSize())
                .fetch();

        JPAQuery<Long> countQuery = queryFactory
                .select(notification.count())
                .from(notification)
                .join(notification.user, user)
                .where(
                        userEmailEq(email),
                        categoryEq(category),
                        isReadEq(isRead)
                );

        return PageableExecutionUtils.getPage(content, pageable, countQuery::fetchOne);
    }

